const {test}=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),vm=require('node:vm');
const {parseHTML}=require('linkedom');const settle=()=>new Promise(r=>setImmediate(r));
async function until(predicate){const deadline=Date.now()+5000;while(!predicate()){if(Date.now()>deadline)throw Error('UI condition did not settle');await settle();}}
const fixture={nodes:[...['user','google','bank','drive','telegram','pdf','diagnostics'].map(id=>({id,label:id,kind:'functional',services:id==='pdf'?['api','pdf-generator','drive-api']:id==='google'?['firebase-auth']:[],endpoints:[],dependencies:[]})),...['api','pdf-generator','drive-api','firebase-auth'].map(id=>({id,label:id,kind:'technical',endpoints:[],dependencies:[]}))],edges:[{from:'user',to:'google'},{from:'google',to:'bank'},{from:'pdf-generator',to:'drive-api'}],events:[],retention:{seconds:3600,maxEvents:100,scope:'instance'},limitations:['Fixture local']};
function setup(fetcher=async()=>new Response(JSON.stringify(fixture))){const {window}=parseHTML(fs.readFileSync('static/admin-architecture.html','utf8')),document=window.document;for(const s of document.querySelectorAll('select'))Object.defineProperty(s,'value',{get(){return this._value??this.firstElementChild?.getAttribute('value')??'';},set(v){this._value=v;}});const originalCreate=document.createElement.bind(document);document.createElement=(tag,...args)=>{const n=originalCreate(tag,...args);if(tag==='select')Object.defineProperty(n,'value',{get(){return this._value??this.firstElementChild?.getAttribute('value')??'';},set(value){this._value=value;}});return n;};let cb,calls=0;const intervals=[];const auth={currentUser:null,onAuthStateChanged(fn){cb=fn;},signOut:async()=>{auth.currentUser=null;cb(null);}};vm.runInNewContext(fs.readFileSync('static/admin-architecture.js','utf8'),{document,firebase:{auth:()=>auth},fetch:async(...args)=>{calls++;return fetcher(...args);},Date,Map,Set,Error,TextEncoder,Uint8Array,crypto:require('node:crypto').webcrypto,setInterval(fn,ms){intervals.push({fn,ms});}});return {document,auth,intervals,submit(form){form.dispatchEvent(new window.Event('submit',{cancelable:true}));},get calls(){return calls;},login(user={getIdToken:async()=> 'fixture'}){auth.currentUser=user;cb(user);},change(id,value){const n=document.getElementById(id);n.value=value;n.dispatchEvent(new window.Event('change'));}};}
test('backend denies unauthorized user and hides all architecture data',async()=>{const ui=setup(async()=>new Response('{}',{status:403}));ui.login();await until(()=>!ui.document.getElementById('access-message').textContent.includes('Validando'));assert.equal(ui.document.querySelector('main').hidden,true);assert.equal(ui.document.getElementById('functional').children.length,0);});
test('missing evidence is never green, diagrams correlate in both directions',async()=>{const ui=setup();ui.login();await until(()=>!ui.document.getElementById('access-message').textContent.includes('Validando'));const d=ui.document;assert.equal(d.querySelector('main').hidden,false);assert.equal(d.querySelectorAll('[data-state="success"]').length,0);d.querySelector('[data-node="pdf"]').click();assert.ok(d.querySelector('[data-node="drive-api"]').classList.contains('related'));d.querySelector('[data-node="firebase-auth"]').click();assert.ok(d.querySelector('[data-node="google"]').classList.contains('related'));});
test('local simulations isolate PDF Drive failure and never send diagnostic writes',async()=>{const ui=setup();ui.login();await until(()=>!ui.document.getElementById('access-message').textContent.includes('Validando'));ui.change('mode','pdf');assert.match(ui.document.getElementById('mode-notice').textContent,/SIMULACIÓN LOCAL/);assert.equal(ui.document.querySelector('[data-node="pdf-generator"]').dataset.state,'success');assert.equal(ui.document.querySelector('[data-node="drive-api"]').dataset.state,'error');assert.equal(ui.document.querySelector('[data-node="firebase-auth"]').dataset.state,'unknown');assert.equal(ui.calls,1);for(const mode of ['oauth','telegram','sync']){ui.change('mode',mode);assert.ok(ui.document.getElementById('alerts').children.length);}ui.change('mode','real');assert.equal(ui.document.querySelectorAll('[data-state="success"]').length,0);assert.equal(ui.calls,1);});
test('logout during token retrieval prevents stale requests',async()=>{let resolve;const ui=setup();ui.login({getIdToken:()=>new Promise(r=>resolve=r)});ui.login(null);resolve('fixture');await settle();assert.equal(ui.calls,0);assert.equal(ui.document.querySelector('main').hidden,true);});
test('logout clears hidden evidence and simulations from DOM',async()=>{const ui=setup();ui.login();await until(()=>!ui.document.getElementById('access-message').textContent.includes('Validando'));ui.change('mode','pdf');ui.login(null);assert.equal(ui.document.getElementById('history').children.length,0);assert.equal(ui.document.getElementById('alerts').children.length,0);assert.equal(ui.document.getElementById('detail').children.length,0);});
test('late previous-account response cannot replace new account data',async()=>{let resolve;const ui=setup(()=>new Promise(r=>resolve=r));ui.login();await settle();ui.login(null);resolve(new Response(JSON.stringify(fixture)));await until(()=>!ui.document.getElementById('access-message').textContent.includes('Validando'));assert.equal(ui.document.getElementById('functional').children.length,0);});
test('confirmed expired event is stale; unconfirmed error is never attributed',async()=>{const data=structuredClone(fixture);data.events=[{id:'old',component:'pdf',service:'pdf-generator',at:'2020-01-01T00:00:00Z',result:'success',confirmed:true},{id:'new',component:'drive',service:'drive-api',at:new Date().toISOString(),result:'error',confirmed:false}];const ui=setup(async()=>new Response(JSON.stringify(data)));ui.login();await until(()=>!ui.document.getElementById('access-message').textContent.includes('Validando'));assert.equal(ui.document.querySelector('[data-node="pdf"]').dataset.state,'stale');assert.equal(ui.document.querySelector('[data-node="drive"]').dataset.state,'unknown');assert.equal(ui.document.getElementById('alerts').children.length,0);});
test('telemetry failure clears evidence and remains recoverable through refresh',async()=>{let fail=false;const ui=setup(async()=>{if(fail)throw Error('network');return new Response(JSON.stringify(fixture));});ui.login();await until(()=>!ui.document.getElementById('access-message').textContent.includes('Validando'));fail=true;ui.document.getElementById('refresh').click();await until(()=>ui.document.querySelector('main').hidden);assert.equal(ui.document.querySelector('main').hidden,true);fail=false;ui.login();await until(()=>!ui.document.querySelector('main').hidden);assert.equal(ui.document.querySelector('main').hidden,false);});

test('failed Drive stage survives later API and read successes while PDF generator stays successful',async()=>{const data=structuredClone(fixture),base=Date.now()-1000;const event=(service,stage,result,i,operationId='pdf-1',component='pdf')=>({id:'e'+i,component,service,stage,result,operationId,at:new Date(base+i*10).toISOString(),confirmed:true});data.events=[event('pdf-generator','generate','success',1),event('drive-api','upload','error',2),event('api','request','success',3),event('drive-api','read','success',4),event('drive-api','upload','success',5,'different-operation')];const ui=setup(async()=>new Response(JSON.stringify(data)));ui.login();await until(()=>!ui.document.querySelector('main').hidden);assert.equal(ui.document.querySelector('[data-node="pdf"]').dataset.state,'error');assert.equal(ui.document.querySelector('[data-node="drive-api"]').dataset.state,'error');assert.equal(ui.document.querySelector('[data-node="pdf-generator"]').dataset.state,'success');ui.document.querySelector('[data-node="pdf"]').click();assert.match(ui.document.getElementById('detail').textContent,/generate/);assert.match(ui.document.getElementById('detail').textContent,/upload/);assert.doesNotMatch(ui.document.getElementById('alerts').textContent,/Resuelta:/);});
test('only later confirmed same operation service and stage resolves a failure',async()=>{const data=structuredClone(fixture),base=Date.now()-1000;data.events=[{component:'pdf',service:'drive-api',stage:'upload',operationId:'pdf-1',result:'error',confirmed:true,at:new Date(base).toISOString()},{component:'pdf',service:'drive-api',stage:'upload',operationId:'pdf-1',result:'success',confirmed:true,at:new Date(base+10).toISOString()}];const ui=setup(async()=>new Response(JSON.stringify(data)));ui.login();await until(()=>!ui.document.querySelector('main').hidden);assert.equal(ui.document.querySelector('[data-node="pdf"]').dataset.state,'success');assert.equal(ui.document.querySelector('[data-node="drive-api"]').dataset.state,'success');assert.match(ui.document.getElementById('alerts').textContent,/Resuelta:/);});

test('automatic refresh is opt-in and pauses in demo, hidden tab and logout',async()=>{const ui=setup();ui.login();await until(()=>!ui.document.querySelector('main').hidden);const timer=ui.intervals.find(t=>t.ms===60000);assert.ok(timer);timer.fn();await settle();assert.equal(ui.calls,1);ui.document.getElementById('auto-refresh').checked=true;timer.fn();await until(()=>ui.calls===2);await until(()=>!ui.document.getElementById('refresh').disabled);ui.change('mode','pdf');timer.fn();await settle();assert.equal(ui.calls,2);ui.change('mode','real');Object.defineProperty(ui.document,'hidden',{value:true,writable:true});timer.fn();await settle();assert.equal(ui.calls,2);ui.document.hidden=false;timer.fn();await until(()=>ui.calls===3);await until(()=>!ui.document.getElementById('refresh').disabled);ui.login(null);timer.fn();await settle();assert.equal(ui.calls,3);assert.equal(ui.document.getElementById('auto-refresh').checked,false);});
test('both diagrams include directional arrow markers',async()=>{const ui=setup();ui.login();await until(()=>!ui.document.querySelector('main').hidden);assert.ok(ui.document.querySelector('#functional marker'));assert.ok(ui.document.querySelector('#technical marker'));assert.match(ui.document.querySelector('#functional path[marker-end]').getAttribute('marker-end'),/arrow-functional/);});
test('browser OAuth warning remains yellow after generic HTTP success in same or another operation',async()=>{for(const operationId of ['tg-connect','other']){const data=structuredClone(fixture);data.nodes.push({id:'telegram-api',label:'Telegram API',kind:'technical'});const base=Date.now()-1000;data.events=[{component:'telegram',service:'drive-api',stage:'drive-authorization',operationId:'tg-connect',confirmed:false,result:'warning',code:'origin_mismatch',at:new Date(base).toISOString()},{component:'telegram',service:'api',stage:'http-backend',operationId,result:'success',confirmed:true,code:'HTTP_200',at:new Date(base+10).toISOString()},{component:'google',service:'firebase-auth',stage:'login',operationId,result:'success',confirmed:true,at:new Date(base+20).toISOString()}];const ui=setup(async()=>new Response(JSON.stringify(data)));ui.login();await until(()=>!ui.document.querySelector('main').hidden);assert.equal(ui.document.querySelector('[data-node="telegram"]').dataset.state,'warning');assert.equal(ui.document.querySelector('[data-node="drive-api"]').dataset.state,'warning');assert.equal(ui.document.querySelectorAll('[data-state="error"]').length,0);assert.match(ui.document.getElementById('alerts').textContent,/Fallo reportado por navegador — causa no verificada por backend/);assert.match(ui.document.getElementById('alerts').textContent,/origen JavaScript autorizado/);assert.ok(ui.document.querySelector('#alerts .warning'));}});
test('Telegram generic status HTTP 200 does not verify the complete functional flow',async()=>{const data=structuredClone(fixture);data.events=[{component:'telegram',service:'api',stage:'http-backend',operationId:'status',confirmed:true,result:'success',code:'HTTP_200',at:new Date().toISOString()}];const ui=setup(async()=>new Response(JSON.stringify(data)));ui.login();await until(()=>!ui.document.querySelector('main').hidden);assert.equal(ui.document.querySelector('[data-node="telegram"]').dataset.state,'unknown');assert.equal(ui.document.querySelector('[data-node="api"]').dataset.state,'success');assert.match(ui.document.getElementById('history').textContent,/Etapa HTTP confirmada \/ flujo no verificado/);});
test('unknown browser error codes never trigger origin mismatch diagnosis',async()=>{const data=structuredClone(fixture);data.events=[{component:'telegram',service:'drive-api',stage:'drive-authorization',operationId:'tg',confirmed:false,result:'warning',code:'untrusted-origin_mismatch-text',at:new Date().toISOString()}];const ui=setup(async()=>new Response(JSON.stringify(data)));ui.login();await until(()=>!ui.document.querySelector('main').hidden);assert.doesNotMatch(ui.document.getElementById('alerts').textContent,/origen JavaScript autorizado/);assert.match(ui.document.getElementById('alerts').textContent,/causa no verificada/);});
test('worker HTTP and identity prerequisite alone do not verify Telegram',async()=>{for(const event of [{service:'worker',stage:'http-backend',code:'200'},{service:'firebase-auth',stage:'identity-verified'}]){const data=structuredClone(fixture);data.events=[{...event,component:'telegram',operationId:'tg',confirmed:true,result:'success',at:new Date().toISOString()}];const ui=setup(async()=>new Response(JSON.stringify(data)));ui.login();await until(()=>!ui.document.querySelector('main').hidden);assert.equal(ui.document.querySelector('[data-node="telegram"]').dataset.state,'unknown');}});
test('pending authorization stays yellow after HTTP 200 without claiming a failure',async()=>{const data=structuredClone(fixture),base=Date.now()-100;data.events=[{component:'telegram',service:'drive-api',stage:'oauth-authorization',operationId:'tg',confirmed:false,result:'warning',code:'authorization_pending',at:new Date(base).toISOString()},{component:'telegram',service:'worker',stage:'http-backend',operationId:'tg',confirmed:true,result:'success',code:'200',at:new Date(base+10).toISOString()}];const ui=setup(async()=>new Response(JSON.stringify(data)));ui.login();await until(()=>!ui.document.querySelector('main').hidden);assert.equal(ui.document.querySelector('[data-node="telegram"]').dataset.state,'warning');assert.match(ui.document.getElementById('alerts').textContent,/Autorización pendiente — sin fallo confirmado/);assert.doesNotMatch(ui.document.getElementById('alerts').textContent,/Fallo reportado|Último fallo confirmado/);assert.match(ui.document.getElementById('history').textContent,/Autorización pendiente — sin fallo confirmado/);assert.match(ui.document.getElementById('alerts').textContent,/volver a la aplicación/);});
