test('HTTP 429 remains a scoped warning and cannot contaminate successful prerequisites sharing operation',async()=>{const data=structuredClone(fixture),base=Date.now()-1000;data.events=[{component:'google',service:'firebase-auth',stage:'identity-verified',operationId:'shared',confirmed:true,result:'success',at:new Date(base).toISOString()},{component:'pdf',service:'pdf-generator',stage:'generate',operationId:'shared',confirmed:true,result:'success',at:new Date(base+10).toISOString()},{component:'telegram',service:'api',stage:'http-backend',operationId:'shared',correlationId:'e578729bc54b4b79a759d6465479950f',code:'429',confirmed:true,result:'error',at:new Date(base+20).toISOString()}];const ui=setup(async()=>new Response(JSON.stringify(data)));ui.login();await until(()=>!ui.document.querySelector('main').hidden);assert.equal(ui.document.querySelector('[data-node="google"]').dataset.state,'success');assert.equal(ui.document.querySelector('[data-node="pdf"]').dataset.state,'success');assert.equal(ui.document.querySelector('[data-node="telegram"]').dataset.state,'warning');assert.equal(ui.document.querySelector('[data-node="api"]').dataset.state,'warning');assert.equal(ui.document.querySelectorAll('[data-state="error"]').length,0);assert.ok(ui.document.querySelector('#alerts .warning'));assert.match(ui.document.getElementById('alerts').textContent,/Causa no determinada/);assert.match(ui.document.getElementById('history').textContent,/Respuesta HTTP 429 confirmada/);});
test('confirmed downstream failure does not recolor successful prerequisites with same operation',async()=>{const data=structuredClone(fixture),at=new Date().toISOString();data.events=[{component:'google',service:'firebase-auth',stage:'identity-verified',operationId:'shared',confirmed:true,result:'success',at},{component:'pdf',service:'pdf-generator',stage:'generate',operationId:'shared',confirmed:true,result:'success',at},{component:'drive',service:'drive-api',stage:'upload',operationId:'shared',confirmed:true,result:'error',code:'403',at}];const ui=setup(async()=>new Response(JSON.stringify(data)));ui.login();await until(()=>!ui.document.querySelector('main').hidden);assert.equal(ui.document.querySelector('[data-node="google"]').dataset.state,'success');assert.equal(ui.document.querySelector('[data-node="pdf"]').dataset.state,'success');assert.equal(ui.document.querySelector('[data-node="drive"]').dataset.state,'error');});
