test('429 exposes actual endpoint and evidence without labeling it a confirmed provider error',async()=>{for(const result of ['warning','error']){const data=structuredClone(fixture);data.events=[{component:'telegram',service:'api',stage:'http-backend',operationId:'limit',endpoint:'/api/telegram/status',code:'429',confirmed:true,result,at:new Date().toISOString()}];const ui=setup(async()=>new Response(JSON.stringify(data)));ui.login();await until(()=>!ui.document.querySelector('main').hidden);assert.equal(ui.document.querySelector('[data-node="api"]').dataset.state,'warning');assert.match(ui.document.getElementById('alerts').textContent,/Endpoint: \/api\/telegram\/status/);assert.match(ui.document.getElementById('alerts').textContent,/Evidencia de la incidencia/);assert.match(ui.document.getElementById('history').textContent,/Endpoint: \/api\/telegram\/status/);ui.document.querySelector('[data-node="api"]').click();assert.match(ui.document.getElementById('detail').textContent,/Sin error confirmado registrado/);}});
const usageFixture={at:'2026-10-17T12:00:00Z',timeZone:'UTC',defaults:{daily:100,monthly:1000},global:{daily:100,monthly:1000,generation:'1'},resets:{daily:'2026-10-18T00:00:00Z',monthly:'2026-11-01T00:00:00Z'},accounts:[{uid:'a',email:'fixture@example.test',displayName:'Cuenta de prueba',usage:{day:'2026-10-17',month:'2026-10',daily:20,monthly:900},limits:{daily:100,monthly:1000},override:null,overrideGeneration:'0'}],nextPageToken:null};
test('usage config loads only manually, renders accessible remaining bars and pagination without polling',async()=>{const requests=[];const ui=setup(async(path,options)=>{requests.push({path,options});if(path.includes('/usage')){const data=structuredClone(usageFixture);if(!path.includes('pageToken'))data.nextPageToken='next/fixture';else data.accounts=[{...data.accounts[0],uid:'b',displayName:'Segunda cuenta',usage:{daily:100,monthly:1000},override:{daily:100,monthly:1000,generation:'3'},overrideGeneration:'3'}];return new Response(JSON.stringify(data));}return new Response(JSON.stringify(fixture));});ui.login();await until(()=>!ui.document.querySelector('main').hidden);assert.equal(requests.length,1);ui.document.getElementById('config-load').click();await until(()=>!ui.document.getElementById('config-content').hidden&&!ui.document.getElementById('config-load').disabled);assert.match(ui.document.getElementById('config-accounts').textContent,/80 restantes/);assert.match(ui.document.getElementById('config-reset').textContent,/hora local/);assert.match(ui.document.getElementById('config-reset').textContent,/UTC/);const schedules=ui.document.querySelectorAll('.usage-period .usage-schedule');assert.equal(schedules.length,2);assert.match(schedules[0].textContent,/Hora de renovación diaria/);assert.match(schedules[1].textContent,/Próximo restablecimiento mensual/);assert.equal(schedules[0].querySelector('time').getAttribute('datetime'),'2026-10-18T00:00:00.000Z');assert.equal(schedules[1].querySelector('time').getAttribute('datetime'),'2026-11-01T00:00:00.000Z');assert.equal(ui.document.querySelectorAll('#config-accounts meter').length,2);assert.equal(ui.document.querySelector('.usage-track').dataset.level,'green');assert.equal(ui.document.querySelectorAll('.usage-track')[1].dataset.level,'orange');assert.equal(requests.filter(r=>r.options?.method==='PUT').length,0);ui.document.getElementById('config-next').click();await until(()=>ui.document.querySelectorAll('.usage-account').length===2&&!ui.document.getElementById('config-load').disabled);assert.ok(requests.some(r=>r.path.includes('pageToken=next%2Ffixture')));assert.equal(ui.document.querySelectorAll('.usage-track')[2].dataset.level,'red');for(const timer of ui.intervals)timer.fn();await settle();assert.equal(requests.length,3);});
test('limit writes require explicit submit and exact admin header, generation and bounded integer inputs',async()=>{const writes=[];const ui=setup(async(path,options)=>{if(options?.method==='PUT'){writes.push(options);return new Response(JSON.stringify({ok:true}));}return new Response(JSON.stringify(path.includes('/usage')?usageFixture:fixture));});ui.login();await until(()=>!ui.document.querySelector('main').hidden);ui.document.getElementById('config-load').click();await until(()=>!ui.document.getElementById('config-load').disabled&&!ui.document.getElementById('config-content').hidden);const form=ui.document.querySelector('#config-global form'),inputs=form.querySelectorAll('input');inputs[0].value='30';inputs[1].value='300';assert.equal(writes.length,0);ui.submit(form);await until(()=>writes.length===1&&!ui.document.getElementById('config-load').disabled);assert.equal(writes[0].headers['X-Requested-With'],'XmlHttpRequest');assert.deepEqual(JSON.parse(writes[0].body),{scope:'global',daily:30,monthly:300,generation:'1'});const accountForm=ui.document.querySelector('#config-accounts form');accountForm.querySelector('input').value='10001';ui.submit(accountForm);await settle();assert.equal(writes.length,1);assert.match(ui.document.getElementById('config-status').textContent,/entre 0 y 10000/);});
test('simulations cannot load or write config and logout clears registered account information',async()=>{const requests=[];const ui=setup(async(path,options)=>{requests.push({path,options});return new Response(JSON.stringify(path.includes('/usage')?usageFixture:fixture));});ui.login();await until(()=>!ui.document.querySelector('main').hidden);ui.document.getElementById('config-load').click();await until(()=>!ui.document.getElementById('config-load').disabled&&!ui.document.getElementById('config-content').hidden);const form=ui.document.querySelector('#config-global form');ui.change('mode','pdf');ui.submit(form);ui.document.getElementById('config-load').click();await settle();assert.equal(requests.length,2);assert.equal(ui.document.getElementById('config-load').disabled,true);ui.login(null);assert.equal(ui.document.getElementById('config-accounts').textContent,'');assert.equal(ui.document.getElementById('config-content').hidden,true);});
test('late config response cannot restore account information after logout',async()=>{let finish;const ui=setup(async path=>path.includes('/usage')?new Promise(resolve=>finish=resolve):new Response(JSON.stringify(fixture)));ui.login();await until(()=>!ui.document.querySelector('main').hidden);ui.document.getElementById('config-load').click();await until(()=>Boolean(finish));ui.login(null);finish(new Response(JSON.stringify(usageFixture)));await settle();await settle();assert.equal(ui.document.getElementById('config-accounts').children.length,0);assert.equal(ui.document.getElementById('config-content').hidden,true);});
test('configuration conflict preserves edited form without claiming it saved',async()=>{const ui=setup(async(path,options)=>options?.method==='PUT'?new Response('{}',{status:409}):new Response(JSON.stringify(path.includes('/usage')?usageFixture:fixture)));ui.login();await until(()=>!ui.document.querySelector('main').hidden);ui.document.getElementById('config-load').click();await until(()=>!ui.document.getElementById('config-load').disabled&&!ui.document.getElementById('config-content').hidden);const form=ui.document.querySelector('#config-global form');form.querySelector('input').value='45';ui.submit(form);await until(()=>!ui.document.getElementById('config-load').disabled);assert.match(ui.document.getElementById('config-status').textContent,/No se guardaron/);assert.equal(form.querySelector('input').value,'45');});
test('deferred token followed by simulation sends no real limit mutation and mode is locked while saving',async()=>{let finish;const writes=[];const ui=setup(async(path,options)=>{if(options?.method==='PUT')writes.push(options);return new Response(JSON.stringify(path.includes('/usage')?usageFixture:fixture));});ui.login();await until(()=>!ui.document.querySelector('main').hidden);ui.document.getElementById('config-load').click();await until(()=>!ui.document.getElementById('config-load').disabled&&!ui.document.getElementById('config-content').hidden);ui.auth.currentUser.getIdToken=()=>new Promise(resolve=>finish=resolve);ui.submit(ui.document.querySelector('#config-global form'));assert.equal(ui.document.getElementById('mode').disabled,true);await until(()=>Boolean(finish));ui.change('mode','pdf');finish('fixture');await until(()=>!ui.document.getElementById('mode').disabled);assert.equal(writes.length,0);assert.match(ui.document.getElementById('config-status').textContent,/simulaciones no modifican/);});
test('account limit inheritance submits only uid and current generation without resetting consumption',async()=>{const data=structuredClone(usageFixture);data.accounts[0].override={daily:30,monthly:300,generation:'7'};data.accounts[0].overrideGeneration='7';const writes=[];const ui=setup(async(path,options)=>{if(options?.method==='PUT'){writes.push(JSON.parse(options.body));return new Response(JSON.stringify({ok:true}));}return new Response(JSON.stringify(path.includes('/usage')?data:fixture));});ui.login();await until(()=>!ui.document.querySelector('main').hidden);ui.document.getElementById('config-load').click();await until(()=>!ui.document.getElementById('config-load').disabled&&!ui.document.getElementById('config-content').hidden);const buttons=ui.document.querySelectorAll('#config-accounts form button');buttons[1].click();await until(()=>writes.length===1&&!ui.document.getElementById('config-load').disabled);assert.deepEqual(writes[0],{scope:'account',uid:'a',inherit:true,generation:'7'});assert.match(ui.document.getElementById('config-accounts').textContent,/20 consumidas/);});
