const accountA='a'.repeat(64),accountB='b'.repeat(64);
function supervisorFixture(events){const data=structuredClone(fixture);data.events=events;data.accounts=[accountA,accountB].map(accountKey=>({accountKey,eventCount:events.filter(e=>e.accountKey===accountKey).length,errorCount:events.filter(e=>e.accountKey===accountKey&&e.result==='error').length,lastAt:events.find(e=>e.accountKey===accountKey)?.at}));data.scope={mode:'global',accountKey:null,totalEvents:events.length,attributedEvents:events.filter(e=>e.accountKey).length,unattributedEvents:events.filter(e=>!e.accountKey).length,visibleEvents:events.length,coverage:'Ventana limitada; no es un historial completo.'};return data;}
function scopedResponse(path,data){const result=structuredClone(data),value=path.includes('?account=')?decodeURIComponent(path.split('?account=')[1]):'';if(value){result.events=result.events.filter(e=>value==='unattributed'?!e.accountKey:e.accountKey===value);result.scope={...result.scope,mode:value==='unattributed'?'unattributed':'account',accountKey:value==='unattributed'?null:value,visibleEvents:result.events.length};}return new Response(JSON.stringify(result));}
test('global account supervision retains one account failure despite another account success and separates alert groups',async()=>{const base=Date.now()-1000,events=[{accountKey:accountA,component:'drive',service:'drive-api',stage:'drive-upload',operationId:'same',endpoint:'/upload',at:new Date(base).toISOString(),confirmed:true,result:'error',code:'403'},{accountKey:accountB,component:'drive',service:'drive-api',stage:'drive-upload',operationId:'same',endpoint:'/upload',at:new Date(base+10).toISOString(),confirmed:true,result:'success'}];const data=supervisorFixture(events),ui=setup(async path=>scopedResponse(path,data));ui.login();await until(()=>!ui.document.querySelector('main').hidden);assert.equal(ui.document.querySelector('[data-node="drive"]').dataset.state,'error');assert.doesNotMatch(ui.document.getElementById('alerts').textContent,/Resuelta:/);assert.match(ui.document.getElementById('history').textContent,/Cuenta aaaaaaaaaaaa/);assert.match(ui.document.getElementById('history').textContent,/Cuenta bbbbbbbbbbbb/);assert.match(ui.document.getElementById('account-scope-status').textContent,/Cobertura: 2 eventos atribuidos de 2/);const errors=supervisorFixture([...events,{...events[0],accountKey:accountB}]),second=setup(async path=>scopedResponse(path,errors));second.login();await until(()=>!second.document.querySelector('main').hidden);assert.equal(second.document.querySelectorAll('#alerts article').length,2);});
test('verified account recovery requires the same operation component service and stage',async()=>{const base=Date.now()-1000,error={accountKey:accountA,component:'drive',service:'drive-api',stage:'drive-upload',operationId:'failed',endpoint:'/upload',at:new Date(base).toISOString(),confirmed:true,result:'error',code:'403'},success={...error,operationId:'retry',result:'success',at:new Date(base+10).toISOString()};for(const [change,recovered]of [[{},false],[{operationId:'failed'},true],[{component:'google'},false],[{service:'api',stage:'http-backend'},false],[{stage:'drive-readback'},false],[{endpoint:'/read'},false],[{accountKey:accountB},false]]){const data=supervisorFixture([error,{...success,...change}]),ui=setup(async path=>scopedResponse(path,data));ui.login();await until(()=>!ui.document.querySelector('main').hidden);assert.equal(ui.document.querySelector('[data-node="drive"]').dataset.state,recovered?'success':'error');}const data=supervisorFixture([{...error,accountKey:null},{...success,accountKey:null}]),ui=setup(async path=>scopedResponse(path,data));ui.login();await until(()=>!ui.document.querySelector('main').hidden);assert.equal(ui.document.querySelector('[data-node="drive"]').dataset.state,'error');});
test('account and unattributed selection queries backend and preserves existing history filters',async()=>{const requests=[],base=Date.now()-1000,data=supervisorFixture([{accountKey:accountA,component:'drive',service:'drive-api',stage:'drive-upload',operationId:'find-me',at:new Date(base).toISOString(),confirmed:true,result:'error',code:'403'},{accountKey:accountB,component:'drive',service:'drive-api',stage:'drive-upload',operationId:'other',at:new Date(base).toISOString(),confirmed:true,result:'success'},{accountKey:null,component:'telegram',service:'api',stage:'browser-request',operationId:'unknown',at:new Date(base).toISOString(),confirmed:false,result:'warning'}]);const ui=setup(async path=>{requests.push(path);return scopedResponse(path,data);});ui.login();await until(()=>!ui.document.querySelector('main').hidden);ui.change('service-filter','drive-api');ui.document.getElementById('operation-filter').value='find-me';ui.change('state-filter','error');ui.change('account-scope',accountA);await until(()=>requests.some(path=>path.endsWith('?account='+accountA))&&!ui.document.getElementById('account-scope').disabled);assert.equal(ui.document.getElementById('service-filter').value,'drive-api');assert.equal(ui.document.getElementById('state-filter').value,'error');assert.equal(ui.document.getElementById('operation-filter').value,'find-me');assert.match(ui.document.getElementById('history').textContent,/find-me/);assert.doesNotMatch(ui.document.getElementById('history').textContent,/bbbbbbbbbbbb/);ui.change('account-scope','unattributed');await until(()=>requests.some(path=>path.endsWith('?account=unattributed'))&&!ui.document.getElementById('account-scope').disabled);assert.match(ui.document.getElementById('account-scope-status').textContent,/Sin atribución/);assert.equal(ui.document.querySelector('[data-node="telegram"]').dataset.state,'warning');ui.login(null);assert.equal(ui.document.getElementById('account-scope').value,'');assert.doesNotMatch(ui.document.getElementById('account-scope').textContent,/aaaaaaaaaaaa/);});
test('configuration account diagnostic link hashes UID locally and requests only its verified reference',async()=>{const expected=require('node:crypto').createHash('sha256').update('a').digest('hex'),requests=[],data=supervisorFixture([]);const ui=setup(async path=>{requests.push(path);return path.includes('/usage')?new Response(JSON.stringify(usageFixture)):scopedResponse(path,data);});await readyAccounts(ui);ui.document.querySelector('[data-account-diagnostic="a"]').click();await until(()=>requests.some(path=>path.endsWith('?account='+expected))&&!ui.document.getElementById('account-scope').disabled);assert.equal(ui.document.getElementById('account-scope').value,expected);assert.match(ui.document.getElementById('account-scope-status').textContent,new RegExp(expected.slice(0,12)));assert.equal(requests.some(path=>path.includes('?uid=')),false);assert.equal(ui.document.getElementById('config-accounts').textContent.includes('fixture@example.test'),true);});
test('simulation pauses real account selection and keeps fictional events isolated',async()=>{const requests=[],data=supervisorFixture([]),ui=setup(async path=>{requests.push(path);return scopedResponse(path,data);});ui.login();await until(()=>!ui.document.querySelector('main').hidden);ui.change('mode','pdf');assert.equal(ui.document.getElementById('account-scope').disabled,true);ui.change('account-scope',accountA);await settle();assert.equal(requests.length,1);assert.match(ui.document.getElementById('history').textContent,/Cuenta ficticia · simulación/);assert.doesNotMatch(ui.document.getElementById('history').textContent,/aaaaaaaaaaaa/);});
test('safe provider reasons add evidence-based advice only on confirmed provider events',async()=>{for(const confirmed of [true,false]){const data=supervisorFixture([{accountKey:accountA,component:'drive',service:'drive-api',stage:'drive-upload',operationId:'quota',confirmed,result:confirmed?'error':'warning',code:'403',reason:'storageQuotaExceeded',at:new Date().toISOString()}]),ui=setup(async path=>scopedResponse(path,data));ui.login();await until(()=>!ui.document.querySelector('main').hidden);if(confirmed){assert.match(ui.document.getElementById('alerts').textContent,/confirmó falta de espacio/);assert.match(ui.document.getElementById('history').textContent,/Motivo verificado: drive_storage_full/);}else{assert.doesNotMatch(ui.document.getElementById('alerts').textContent,/confirmó falta de espacio/);assert.match(ui.document.getElementById('alerts').textContent,/causa no verificada/);}}});
test('HTTP 200 receipt of browser telemetry never verifies Google or Drive and cannot resolve browser failure',async()=>{const base=Date.now()-1000,data=supervisorFixture([{accountKey:accountA,component:'drive',service:'drive-api',stage:'oauth-authorization',operationId:'client',endpoint:'/api/diagnostics/client',confirmed:false,result:'warning',code:'origin_mismatch',at:new Date(base).toISOString()},{accountKey:accountA,component:'drive',service:'drive-api',stage:'oauth-authorization',operationId:'client',endpoint:'/api/diagnostics/client',confirmed:true,result:'success',at:new Date(base+10).toISOString()},{accountKey:accountA,component:'google',service:'api',stage:'http-backend',operationId:'client',endpoint:'/api/diagnostics/client',confirmed:true,result:'success',code:'200',at:new Date(base+20).toISOString()}]),ui=setup(async path=>scopedResponse(path,data));ui.login();await until(()=>!ui.document.querySelector('main').hidden);assert.equal(ui.document.querySelector('[data-node="drive"]').dataset.state,'warning');assert.equal(ui.document.querySelector('[data-node="google"]').dataset.state,'unknown');assert.doesNotMatch(ui.document.getElementById('alerts').textContent,/Resuelta:/);assert.match(ui.document.getElementById('history').textContent,/Recepción de telemetría confirmada \/ flujo no verificado/);assert.match(ui.document.getElementById('alerts').textContent,/causa no verificada por backend/);});

function mockDialog(dialog){dialog.showModal=function(){this.open=true;};dialog.close=function(){this.open=false;};}
test('navigation opens separate dialogs and account plan cancellation restores configuration',async()=>{const ui=setup(async path=>new Response(JSON.stringify(path.includes('/usage')?usageCatalogFixture:fixture)));await readyAccounts(ui);const d=ui.document;for(const id of ['config-dialog','plans-dialog','review-dialog'])mockDialog(d.getElementById(id));d.getElementById('open-config').click();assert.equal(d.getElementById('config-dialog').open,true);d.getElementById('open-plans').click();assert.equal(d.getElementById('plans-dialog').open,true);d.querySelector('#plans-dialog .dialog-close').click();assert.equal(d.getElementById('plans-dialog').open,false);d.querySelector('[data-account-plan="a"]').click();assert.equal(d.getElementById('review-dialog').open,true);assert.ok(d.querySelector('#review-dialog #user-plan-name'));d.querySelector('[data-cancel-user-plan]').click();assert.equal(d.getElementById('review-dialog').open,false);assert.equal(d.getElementById('config-dialog').open,true);ui.login(null);assert.equal(d.getElementById('config-dialog').open,false);assert.equal(d.querySelector('main').hidden,true);});

test('Plans opens independently and loads only by explicit navigation without mutations',async()=>{const requests=[];const ui=setup(async(path,options)=>{requests.push({path,method:options?.method||'GET'});return new Response(JSON.stringify(path.includes('/usage')?usageCatalogFixture:fixture));});ui.login();await until(()=>!ui.document.querySelector('main').hidden);const d=ui.document;mockDialog(d.getElementById('config-dialog'));mockDialog(d.getElementById('plans-dialog'));assert.equal(requests.length,1);d.getElementById('open-plans').click();await until(()=>d.querySelector('.catalog-editor form'));assert.equal(d.getElementById('plans-dialog').open,true);assert.notEqual(d.getElementById('config-dialog').open,true);assert.equal(requests.filter(item=>item.path.includes('/usage')).length,1);assert.ok(requests.every(item=>item.method==='GET'));d.querySelector('#plans-dialog [data-close-dialog]').click();assert.equal(d.getElementById('plans-dialog').open,false);d.getElementById('open-plans').click();await settle();assert.equal(requests.length,2);ui.change('mode','pdf');assert.equal(d.getElementById('plans-load').disabled,true);assert.equal(d.querySelector('[data-save-plan-catalog]').disabled,true);assert.equal(d.querySelector('#plans-dialog [data-close-dialog]').disabled,false);ui.login(null);assert.equal(d.getElementById('plans-content').children.length,0);assert.equal(d.getElementById('plans-dialog').open,false);});

test('attributed OAuth pending requires canonical confirmation for the exact operation',async()=>{
 for(const variant of ['other-operation','userinfo-only','canonical']){
  const data=structuredClone(fixture),accountKey='a'.repeat(64),base=Date.now()-1000;
  data.events=[{component:'google',service:'drive-api',stage:'oauth-authorization',operationId:'connect-1',accountKey,result:'warning',confirmed:false,code:'authorization_pending',at:new Date(base).toISOString()},
   {component:variant==='userinfo-only'?'drive':'google',service:'drive-api',stage:'oauth-authorization',operationId:variant==='other-operation'?'connect-2':'connect-1',accountKey,result:'success',confirmed:true,at:new Date(base+10).toISOString()}];
  const ui=setup(async()=>new Response(JSON.stringify(data)));ui.login();await until(()=>!ui.document.querySelector('main').hidden);
  assert.equal(ui.document.querySelector('[data-node="google"]').dataset.state,variant==='canonical'?'success':'warning',variant);
  const alerts=ui.document.getElementById('alerts').textContent;
  if(variant==='canonical'){assert.match(alerts,/Resuelta:/);assert.doesNotMatch(alerts,/Completar la autorización|volver a la aplicación/);assert.match(alerts,/se conserva como historial/);}
  else assert.doesNotMatch(alerts,/Resuelta:/);
 }
});

