test('explicit later connection check recovers current access while retaining original attempt history',async()=>{
 const base=Date.now()-1000,accountKey='a'.repeat(64);
 for(const variant of ['verified','other-account','unattributed','wrong-stage','ordinary-endpoint']){
  const data=structuredClone(fixture),pending={component:'google',service:'drive-api',stage:'oauth-authorization',operationId:'old-popup',accountKey:variant==='unattributed'?null:accountKey,result:'warning',confirmed:false,code:'authorization_pending',at:new Date(base).toISOString()};
  data.events=[pending,{...pending,operationId:'new-sync',endpoint:variant==='ordinary-endpoint'?'/api/google/grant':'/api/account/connections/verify',accountKey:variant==='other-account'?'b'.repeat(64):pending.accountKey,stage:variant==='wrong-stage'?'drive-readback':pending.stage,result:'success',confirmed:true,code:'200',at:new Date(base+10).toISOString()}];
  const ui=setup(async()=>new Response(JSON.stringify(data)));ui.login();await until(()=>!ui.document.querySelector('main').hidden);
  assert.equal(ui.document.querySelector('[data-node="google"]').dataset.state,variant==='verified'?'success':'warning',variant);
  const alerts=ui.document.getElementById('alerts').textContent;
  assert.doesNotMatch(alerts,/Resuelta:/);
  if(variant==='verified'){assert.match(alerts,/Acceso verificado de nuevo; el intento original no se confirmó/);assert.doesNotMatch(alerts,/Completar la autorización|volver a la aplicación/);assert.match(ui.document.getElementById('history').textContent,/old-popup/);}
  else assert.doesNotMatch(alerts,/Acceso verificado de nuevo/);
 }
});

